/** SAS in the editors: the one-line SAS sentence each mapping and prep step is, the SAS ▸
 *  toggle that opens its full statements, a live-checked SAS code field, and the searchable
 *  function catalog. Everything shown is generated by the server from the same code the SAS
 *  program writes, so what a reader sees here is what the program will say. */
import { useEffect, useMemo, useRef, useState, type ReactNode } from "react"
import { Search } from "lucide-react"
import { api } from "@/api"
import type { SasFunction } from "@/api"
import { sasSentence, useSasCatalog } from "./sasHooks"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { Textarea } from "@/components/ui/textarea"
import { cn } from "@/lib/utils"

/** A one-line SAS sentence with the SAS ▸ toggle; open, it shows the full statements.
 *  The editing controls (children) stay below in both views. */
export function SasForm({ lines, title, children, className }: {
  lines: string[]; title?: ReactNode; children?: ReactNode; className?: string
}) {
  const [full, setFull] = useState(false)
  const line = sasSentence(lines)
  const more = lines.filter((l) => l.trim() && !/^(run;|quit;)$/i.test(l.trim())).length
    - lines.filter((l) => l.trim() && line.includes(l.trim())).length
  return (
    <div className={cn("overflow-hidden rounded-lg border bg-muted/20", className)}>
      <div className="flex items-center gap-2 border-b px-2.5 py-1.5">
        {title && <span className="shrink-0 text-[10px] font-semibold uppercase tracking-wide text-muted-foreground">{title}</span>}
        <code className="min-w-0 flex-1 truncate font-mono text-[11.5px] text-sky-700 dark:text-sky-300" title={line}>
          {line || "…"}
        </code>
        {more > 0 && !full && <span className="shrink-0 text-[10px] text-muted-foreground">+{more} more step{more > 1 ? "s" : ""}</span>}
        <button type="button" onClick={() => setFull((f) => !f)}
                title={full ? "back to the one-line view" : "show the full SAS statements"}
                className={cn("shrink-0 rounded border px-1.5 py-0.5 font-mono text-[10px] font-bold",
                              full ? "border-sky-500 text-sky-700 dark:text-sky-300" : "text-muted-foreground")}>
          SAS {full ? "▾" : "▸"}
        </button>
      </div>
      {full && (
        <pre className="max-h-64 overflow-auto border-b bg-background/60 px-3 py-2 font-mono text-[11px] leading-relaxed">
          {lines.join("\n")}
        </pre>
      )}
      {children && <div className="p-3">{children}</div>}
    </div>
  )
}

/** A SAS code box: type an expression or IF / ELSE statements; checked as you type, with the
 *  function catalog one click away. */
export function SasCodeField({ value, onChange, variable = "", rows = 3, placeholder }: {
  value: string; onChange: (v: string) => void; variable?: string; rows?: number; placeholder?: string
}) {
  const ref = useRef<HTMLTextAreaElement>(null)
  const [check, setCheck] = useState<{ ok: boolean; error?: string; names?: string[]; sas?: string[] } | null>(null)
  useEffect(() => {
    if (!value.trim()) return
    let live = true
    const t = window.setTimeout(() => {
      api.sasCheck(value, variable).then((r) => { if (live) setCheck(r) }).catch(() => undefined)
    }, 300)
    return () => { live = false; window.clearTimeout(t) }
  }, [value, variable])
  const insert = (text: string) => {
    const el = ref.current
    const at = el ? el.selectionStart : value.length
    const end = el ? el.selectionEnd : value.length
    onChange(value.slice(0, at) + text + value.slice(end))
    window.setTimeout(() => {
      el?.focus()
      const caret = at + (text.indexOf("(") >= 0 ? text.indexOf("(") + 1 : text.length)
      el?.setSelectionRange(caret, caret)
    }, 0)
  }
  return (
    <div className="space-y-1.5">
      <Textarea ref={ref} rows={rows} spellCheck={false} placeholder={placeholder}
                className="font-mono text-xs" value={value} onChange={(e) => onChange(e.target.value)} />
      <div className="flex flex-wrap items-start gap-2">
        <FunctionPicker onPick={(f) => insert(`${f.name}()`)} />
        {check && value.trim() && (check.ok
          ? <span className="min-w-0 flex-1 text-[11px] text-emerald-700 dark:text-emerald-400">
              ✓ SAS — reads {(check.names ?? []).join(", ") || "no columns"}
              <code className="ml-1.5 font-mono text-[10.5px] text-muted-foreground">{(check.sas ?? []).join(" ")}</code>
            </span>
          : <span className="min-w-0 flex-1 text-[11px] text-destructive">✗ {check.error}</span>)}
      </div>
    </div>
  )
}

/** The searchable, categorised function catalog; picking one inserts its call. */
export function FunctionPicker({ onPick }: { onPick: (f: SasFunction) => void }) {
  const cat = useSasCatalog()
  const [open, setOpen] = useState(false)
  const [q, setQ] = useState("")
  const [category, setCategory] = useState("")
  const found = useMemo(() => {
    const t = q.trim().toLowerCase()
    return (cat?.functions ?? []).filter((f) =>
      (!category || f.category === category) &&
      (!t || f.name.includes(t) || f.summary.toLowerCase().includes(t) || f.syntax.toLowerCase().includes(t)))
  }, [cat, q, category])
  if (!open) {
    return <Button type="button" variant="outline" size="sm" className="h-7 text-[11px]"
                   onClick={() => setOpen(true)}>ƒ Insert a SAS function…</Button>
  }
  return (
    <div className="w-full space-y-2 rounded-lg border bg-background p-2">
      <div className="flex flex-wrap items-center gap-2">
        <span className="relative min-w-48 flex-1">
          <Search className="absolute left-2 top-2 h-3.5 w-3.5 text-muted-foreground" />
          <Input autoFocus className="h-8 pl-7 text-xs" placeholder="search — e.g. date, scan, missing"
                 value={q} onChange={(e) => setQ(e.target.value)} />
        </span>
        <Button type="button" variant="ghost" size="sm" className="h-7 text-[11px]"
                onClick={() => setOpen(false)}>Close</Button>
      </div>
      <div className="flex flex-wrap gap-1">
        {["", ...(cat?.categories ?? [])].map((c) => (
          <button key={c || "all"} type="button" onClick={() => setCategory(c)}
                  className={cn("rounded-full border px-2 py-0.5 text-[10.5px]",
                                category === c ? "border-sky-500 bg-sky-500/10 text-sky-700 dark:text-sky-300"
                                               : "text-muted-foreground")}>
            {c || "All"}
          </button>
        ))}
      </div>
      <div className="max-h-64 overflow-auto rounded border">
        {found.map((f) => (
          <button key={f.name} type="button" onClick={() => { onPick(f); setOpen(false) }}
                  className="block w-full border-b px-2.5 py-1.5 text-left last:border-b-0 hover:bg-muted/50">
            <code className="font-mono text-[11.5px] font-semibold">{f.syntax}</code>
            <span className="ml-2 text-[11px] text-muted-foreground">{f.summary}</span>
            <code className="block font-mono text-[10.5px] text-muted-foreground">{f.example}</code>
          </button>
        ))}
        {!found.length && <p className="p-3 text-[11px] text-muted-foreground">No function matches.</p>}
      </div>
    </div>
  )
}
